-- The copies (owner, 25 Nov 2026): BUA203 is LAG-ACS209, LAG-BUA210 is LAG-ACS213 under another code. Each
-- publishes its source's bank and guide topics on its own course. Each copy is its source exactly, with ids of its own;
-- what the owner content rule withdrew stays withdrawn, and no theory or overview is published. A student of the copy's
-- department reads it under its own code and title, a student of the source's department reads the source as before,
-- and Campus Bot names the course the student is on. The rule runs again only once the copies are rolled back.
begin;
select no_plan();

-- A course's published items of one kind: source key, payload and place.
create function pg_temp.published(p_course uuid, p_kind text) returns table (source_key text, payload jsonb, place integer)
language sql stable as $$
  select i.source_key, r.payload, i.position from public.managed_content_items i
  join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
  where i.course_id = p_course and i.kind = p_kind $$;
create function pg_temp.count(p_course uuid, p_kind text) returns integer language sql stable as $$
  select count(*)::integer from public.managed_content_items
  where course_id = p_course and kind = p_kind and published_revision is not null $$;
-- A 200 level, first semester student of the first department (by key) that takes the course, on the free month: the
-- student's own courses and Campus Bot.
create function pg_temp.student(p_n integer, p_code text) returns void language plpgsql as $$
begin
  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data,
    raw_user_meta_data, created_at, updated_at)
  values ('00000000-0000-0000-0000-000000000000', ('c0b10000-0000-4000-8000-' || lpad(p_n::text, 12, '0'))::uuid,
    'authenticated', 'authenticated', 'copies-' || p_n || '@example.test', 'x', now(),
    '{"provider":"email","providers":["email"]}', '{}', now(), now());
  insert into auth.sessions (id, user_id, created_at, updated_at) values (('c0b20000-0000-4000-8000-' || lpad(p_n::text, 12, '0'))::uuid,
    ('c0b10000-0000-4000-8000-' || lpad(p_n::text, 12, '0'))::uuid, now(), now());
  update public.profiles set first_name = 'Ada', department_id = (select a.department_id from public.course_applicability a
      join public.institutional_courses c on c.id = a.institutional_course_id join public.departments d on d.id = a.department_id
      join public.academic_levels l on l.id = a.academic_level_id and l.key = '200-level'
      join public.academic_periods p on p.id = a.academic_period_id and p.key = 'first-semester'
      where c.course_code = p_code order by d.key limit 1),
    academic_level_id = (select id from public.academic_levels where key = '200-level'),
    academic_period_id = (select id from public.academic_periods where key = 'first-semester')
    where id = ('c0b10000-0000-4000-8000-' || lpad(p_n::text, 12, '0'))::uuid;
  insert into public.entitlement_grants (user_id, source, starts_at, ends_at, ai_terms, ai_units, created_by)
    values (('c0b10000-0000-4000-8000-' || lpad(p_n::text, 12, '0'))::uuid, 'early_access', now() - interval '1 day',
      now() + interval '20 days', 'uncapped', null, 'copies-test');
end $$;
-- The course's first published note, as Ask Campus Bot opens it.
create function pg_temp.first_note(p_course uuid) returns uuid language sql stable as $$
  select id from public.managed_content_items where course_id = p_course and kind = 'note' and published_revision is not null
  order by position nulls last, created_at, id limit 1 $$;
update private.campus_bot_settings set ask_enabled = true;

